import{c as a,Q as s,j as n,m as t}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"How to use NLPM","description":"","frontmatter":{"title":"How to use NLPM","outline":[2,3]},"headers":[],"relativePath":"how-to-use-it.md","filePath":"how-to-use-it.md","lastUpdated":1786596316000}'),o={name:"how-to-use-it.md"};function i(c,e,l,p,r,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="how-to-use-nlpm" tabindex="-1">How to use NLPM <a class="header-anchor" href="#how-to-use-nlpm" aria-label="Permalink to &quot;How to use NLPM&quot;">​</a></h1><p>Every interactive workflow is an explicit Codex skill. Run it from the repository you want to inspect.</p><h2 id="core-loop" tabindex="-1">Core loop <a class="header-anchor" href="#core-loop" aria-label="Permalink to &quot;Core loop&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$nlpm-init</span></span>
<span class="line"><span>$nlpm-ls</span></span>
<span class="line"><span>$nlpm-score --changed</span></span>
<span class="line"><span>$nlpm-check</span></span>
<span class="line"><span>$nlpm-fix</span></span>
<span class="line"><span>$nlpm-test</span></span>
<span class="line"><span>$nlpm-trend</span></span>
<span class="line"><span>$nlpm-report</span></span></code></pre></div><ul><li><code>$nlpm-init</code> writes project policy to <code>.codex/nlpm.local.md</code> and captures a baseline.</li><li><code>$nlpm-ls [path]</code> inventories supported NL artifacts.</li><li><code>$nlpm-score [path|--changed]</code> delegates scorer and vague-word passes in parallel and appends history.</li><li><code>$nlpm-check [path]</code> checks references, registration, contradictions, and vocabulary.</li><li><code>$nlpm-fix [path]</code> applies only documented mechanical repairs, then rescores.</li><li><code>$nlpm-test [spec]</code> evaluates <code>.nlpm-test/*.spec.md</code> files.</li><li><code>$nlpm-trend [path]</code> compares snapshots with matching scopes.</li><li><code>$nlpm-report [path]</code> writes <code>.codex/nlpm-reports/index.html</code>.</li></ul><h2 id="security-and-vocabulary" tabindex="-1">Security and vocabulary <a class="header-anchor" href="#security-and-vocabulary" aria-label="Permalink to &quot;Security and vocabulary&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$nlpm-security-scan</span></span>
<span class="line"><span>$nlpm-vocab-init</span></span>
<span class="line"><span>$nlpm-vocab-drift</span></span></code></pre></div><p>The security scan reads executable surfaces without executing the inspected code. Vocabulary initialization creates a reviewable registry; drift scanning is advisory and requires no registry.</p><h2 id="specification-maintenance" tabindex="-1">Specification maintenance <a class="header-anchor" href="#specification-maintenance" aria-label="Permalink to &quot;Specification maintenance&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$nlpm-spec-sync codex</span></span>
<span class="line"><span>$nlpm-spec-sync all</span></span></code></pre></div><p>The workflow browses official upstream documentation, delegates one read-only researcher per selected overlay, applies only well-supported corrections, and runs <code>bin/nlpm-check</code>. It never commits or pushes.</p><h2 id="state-and-hooks" tabindex="-1">State and hooks <a class="header-anchor" href="#state-and-hooks" aria-label="Permalink to &quot;State and hooks&quot;">​</a></h2><p>NLPM writes runtime state only below <code>.codex/</code>. Its <code>PostToolUse</code> hook watches Codex file edits, stays silent for non-NL files, and adds a <code>$nlpm-score</code> reminder for matching artifacts. Malformed hook input fails open.</p><h2 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;CI&quot;">​</a></h2><p>Use <code>python3 bin/nlpm-check .</code> for the deterministic floor. NLPM&#39;s own judgment-based Auditor jobs use <code>openai/codex-action@v1</code> with <code>OPENAI_API_KEY</code>.</p><p>The rubric remains multi-tool: Claude Code and Antigravity formats can be discovered and scored as data, but neither runtime is required or invoked.</p>`,16)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
